mapper.select:
/* 요금제 약정기간 조회 : MspMapper.selectMspSaleAgrmMst :: 해당정책코드에 해당하는 약정개월정보(무약정 포함) 리스트 조회 */ SELECT RA.AGRM_TRM
FROM MSP_SALE_AGRM_MST RA WHERE 1=1
AND RA.SALE_PLCY_CD = #{salePlcyCd}
GROUP BY RA.AGRM_TRM ORDER BY RA.AGRM_TRM

/* 휴대폰 할부개월 조회 : AppformMapper.selectModelMonthlyList */ SELECT INST_NOM AS MODEL_MONTHLY FROM ORG_INST_NOM_MST WHERE 1=1
AND SALE_PLCY_CD = #{salePlcyCd}
GROUP BY INST_NOM ORDER BY INST_NOM

/* 할인유형조회 */ SELECT DISTINCT PL.SPRT_TP, --할인유형 (SELECT DTL_CD_NM FROM NMCP_CD_DTL@DL_MCP WHERE CD_GROUP_ID='F002' AND USE_YN='Y' AND PL.SPRT_TP=DTL_CD) AS SPRT_NM --할인유형명 FROM MSP_SALE_PLCY_MST PL, MSP_SALE_ORGN_MST ORG, MSP_SALE_PRDT_MST PRDT WHERE PL.CNFM_YN='Y' -- 결제 YN (필수) AND PL.SALE_PLCY_CD = ORG.SALE_PLCY_CD AND PL.SALE_PLCY_CD = PRDT.SALE_PLCY_CD AND ORG.SALE_PLCY_cD = PRDT.SALE_PLCY_CD AND TO_CHAR(SYSDATE,'yyyymmddhh24miss') BETWEEN PL.SALE_STRT_DTTM AND PL.SALE_END_DTTM --판매기간 (필수) AND PL.PLCY_TYPE_CD = #{plcyTypeCd} -- 정책코드 : N(스마트 임의적용) , 온라인:O , 오프라인:M , 직영온라인 : D AND PL.PLCY_SCTN_CD = #{reqBuyTypeCd.rateType} -- 없을경우 eNum 으로 01고정값 // MM:단말(01),UU:유심(02) AND ORG.ORGN_ID = #{agentCd} -- 조직코드
AND PRDT.PRDT_ID = #{prdtId} -- 단말기ID (자급제인 경우는 SKIP 처리)
AND PL.SALE_PLCY_CD = #{salePlcyCd}
AND PL.PRDT_SCTN_CD = #{prdtSctnCd} -- LTE,3G

/*MspMapper.listMspSalePrdtMstBySalePlcyCd 정책에 해당하는 상품의 상세정보를 가져온다.*/ SELECT CMN.PRDT_ID, CMN.PRDT_NM PROD_NM, CMN.RPRS_PRDT_ID MODEL_ID, CMN.PRDT_CODE REQ_MODEL_NM, (SELECT MAX(PROD_ID) FROM NMCP_PROD_BAS@DL_MCP WHERE RPRS_PRDT_ID = CMN.RPRS_PRDT_ID AND SALE_YN='Y') PROD_ID, CMN.PRDT_TYPE_CD, -- 제품유형코드 CMN.PRDT_IND_CD, -- 제품구분코드 CMN.PRDT_COLR_CD, -- 제품색상코드 CMN.RPRS_YN, CMN.MNFCT_ID, SALE.SALE_PLCY_CD, SALE.PRDT_ID AS S_PRDT_ID, SALE.OLD_YN, SALE.NEW_CMSN_AMT, SALE.MNP_CMSN_AMT, SALE.HCN_CMSN_AMT FROM MSP_SALE_PRDT_MST SALE INNER JOIN CMN_INTM_MDL CMN ON SALE.PRDT_ID = CMN.PRDT_ID WHERE 1=1
AND SALE.SALE_PLCY_CD IN
#{prdt.salePlcyCd}
AND PRDT_TYPE_CD = '01' -- 제품유형코드 --AND PRDT_IND_CD = '04' -- 제품구분코드 AND OLD_YN='N' -- 중고여부 AND RPRS_YN='Y' --대표여부 AND PRDT_DT >= TO_CHAR(SYSDATE, 'YYYYMMDD') -- 제품단종일자

/* 핸드폰 색상 목록 조회 AppformMapper.selectPrdtColorList */ SELECT A.PRDT_COLR_CD AS MODEL_COLOR_CD ,B.CD_DSC AS MODEL_COLOR_NM
FROM CMN_INTM_MDL A , CMN_GRP_CD_MST B WHERE A.RPRS_YN = 'N' AND A.PRDT_COLR_CD = B.CD_VAL AND B.GRP_ID = 'CMN0044'
AND A.RPRS_PRDT_ID = #{rprsPrdtId}

/* 휴대폰 용량 목록 조회 PhoneMapper.triggerSelectProdBasImgDtlList */ SELECT A.ATRIB_VAL_CD_2 AS MODEL_CAPACITY_CD ,A.ATRIB_VAL_NM_2 AS MODEL_CAPACITY_NM
FROM NMCP_SNTY_PROD_BAS@DL_MCP A , NMCP_PROD_ATRIB_VAL_DTL@DL_MCP B WHERE 1=1 AND A.ATRIB_VAL_CD_2 = A.ATRIB_VAL_CD_2 AND B.ATRIB_CD='P0'
AND A.PROD_ID = #{prodId}
GROUP BY A.PROD_ID,A.ATRIB_VAL_CD_2,A.ATRIB_VAL_NM_2

/* StoreUsimMapper.selectUsimDcamt */ SELECT TRUNC(NVL(BASE_AMT,0) * 1.1) AS BASE_AMT ,TRUNC(NVL(DC_AMT,0) * 1.1) AS DC_AMT FROM MSP_RATE_MST A, MSP_RATE_SPEC B WHERE A.RATE_CD = B.RATE_CD(+) AND A.RATE_CD = #{rateCd}
AND B.AGRM_TRM(+) ='0' AND A.APPL_END_DT = '99991231'
AND ROWNUM =1 ORDER BY B.APPL_STRT_DTTM DESC

/** 부가서비스 상세 정보 조회 **/ SELECT A.RATE_CD, A.RATE_NM, A.BASE_AMT, C.ADDITION_KEY FROM MCP_ADDITION@DL_MCP C LEFT JOIN MSP_SALE_RATE_MST B ON B.RATE_CD = C.SOC LEFT JOIN MSP_RATE_MST A ON C.SOC = A.RATE_CD WHERE 1=1 AND A.SERVICE_TYPE = 'R' AND B.SALE_PLCY_CD IS NULL
AND C.SOC IN
#{addRate.prodId}

SELECT A.RATE_ADSVC_CD AS RATE_CD , M.RATE_NM , NVL(M.BASE_AMT, 0) AS BASE_AMT , C.ADDITION_KEY , B.USE_PRD FROM ( SELECT RATE_ADSVC_PROD_REL_SEQ, RATE_ADSVC_GDNC_SEQ, RATE_ADSVC_CD FROM NMCP_RATE_ADSVC_GDNC_PROD_REL@DL_MCP WHERE 1=1 AND RATE_ADSVC_CD IN
#{addRate.prodId}
AND USE_YN = 'Y' AND PSTNG_START_DATE < TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') ) A INNER JOIN ( SELECT RATE_ADSVC_GDNC_SEQ, USE_PRD FROM NMCP_RATE_ADSVC_GDNC_BAS@DL_MCP WHERE 1=1 AND USE_YN = 'Y' AND PSTNG_START_DATE < TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') AND USE_PRD IS NOT NULL AND USE_PRD != '0' -- 무료 부가서비스는 일정액 상품에 등록되어 있더라도 일정액 상품에서 제외처리 (2026.07.01) ) B ON B.RATE_ADSVC_GDNC_SEQ = A.RATE_ADSVC_GDNC_SEQ LEFT JOIN MSP_RATE_MST M ON M.RATE_CD = A.RATE_ADSVC_CD AND M.APPL_END_DT = '99991231' LEFT JOIN MCP_ADDITION@DL_MCP C ON C.SOC = A.RATE_ADSVC_CD

/*MspMapper.findMspSaleSubsdMst 상품의 판매금액관련 상세내역을 조회 한다.*/ SELECT SALE_PLCY_CD, --판매정책코드 RATE_CD, --요금제코드 PRDT_ID, --제품ID AGRM_TRM, --약정기간 OPER_TYPE, --업무유형 HNDST_AMT, --단말금액(VAT포함) SUBSD_AMT, --공시지원금(VAT포함) INST_AMT, --할부원금(VAT포함) INST_CMSN, --할부수수료(VAT포함) AGNCY_SUBSD_MAX, --대리점보조금MAX(VAT포함) AGNCY_SUBSD_AMT, --대리점보조금(VAT포함) SPRT_TP, --지원금유형 TRUNC(NVL(BASE_AMT,0) * 1.1) AS BASE_AMT, --기본료 TRUNC(NVL(DC_AMT,0) * 1.1) AS DC_AMT, --기본할인금액 TRUNC(NVL(ADD_DC_AMT,0) * 1.1) AS ADD_DC_AMT --추가할인금액 FROM MSP_SALE_SUBSD_MST WHERE 1=1 AND OLD_YN = #{oldYn} --중고여부 AND ORGN_ID = #{agentCd} --조직코드 AND OPER_TYPE = #{operTypeCd} --가입유형 (NAC3 , MNP3 , HDN3) AND SALE_PLCY_CD = #{salePlcyCd} --판매정책코드 AND AGRM_TRM = #{agrmTrm} --약정기간 AND PRDT_ID = #{modelId} --상품ID AND RATE_CD = #{rateCd} --요금제코드
AND SPRT_TP =#{sprtTp} --할인유형 (단말 KD , 요금 PM) 이 없는 데이타가 있어 조건 추가
AND ROWNUM = 1
